import {chromium} from '@playwright/test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {KEY,scenarioState,makeTask} from '../src/model.js';
const dir=process.env.ACTION_CYCLE_EVIDENCE_DIR||'检查记录/执行复盘重设计_20261021',base='http://127.0.0.1:5184';
await fs.mkdir(dir,{recursive:true});
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']});
const p=await browser.newPage({viewport:{width:1440,height:1000}}),results=[],errors=[];p.setDefaultTimeout(6000);p.on('pageerror',e=>errors.push(e.message));
async function load(route,s='PT05',width=1440,lang='zh'){await p.setViewportSize({width,height:width<720?844:1000});await p.goto(base);await p.evaluate(({s,k,lang})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true,active:null,seen:[]}));},{s:typeof s==='string'?scenarioState(s):s,k:KEY,lang});await p.goto(base+route);await p.locator('.action-cycle').waitFor();await p.emulateMedia({reducedMotion:'reduce'});await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});const toast=p.locator('.toast.show button');if(await toast.count())await toast.click();}
const state=()=>p.evaluate(k=>JSON.parse(localStorage.getItem(k)),KEY);
async function shot(name,selector='.action-cycle'){await p.locator(selector).evaluate(e=>e.scrollIntoView({block:'start'}));await p.screenshot({path:dir+'/'+name+'-视口.png'});const v=p.viewportSize(),box=await p.locator(selector).boundingBox();await p.setViewportSize({width:v.width,height:Math.ceil(box.height+650)});const style=await p.addStyleTag({content:'.flow-progress{visibility:hidden!important}'});await p.locator(selector).screenshot({path:dir+'/'+name+'-板块.png'});await style.evaluate(e=>e.remove());await p.setViewportSize(v);}
async function check(name,fn){try{await fn();results.push({name,status:'pass'});console.log('PASS',name);}catch(e){results.push({name,status:'fail',error:e.message});console.log('FAIL',name,e.message.slice(0,700));await p.screenshot({path:dir+'/失败-'+results.length+'.png'});}}
try{
await check('空执行页可起草交付并进入原预算预检，尚未创建任务',async()=>{await load('/plan?tab=执行','PT01');await shot('1440-执行起点');await p.getByLabel('任务目的',{exact:true}).fill('如何解释数据异常');await p.getByLabel('预期产物',{exact:true}).fill('问题清单和局限');await p.getByRole('button',{name:'检查范围与预算',exact:true}).click();assert.equal(await p.locator('dialog[open]').count(),1);assert.equal((await state()).tasks.length,0);assert.equal((await state()).taskDraft.purpose,'如何解释数据异常');assert.equal((await state()).taskDraft.product,'问题清单和局限');});
await check('队列按阻塞优先，筛选与详情关联同一任务，开始仍进入原S2工作区',async()=>{const s=scenarioState('PT05');s.tasks.push({...makeTask(s,{title:'受阻行动（合成）',hours:1,purpose:'澄清输入',product:'输入说明'}),id:'blocked',status:'受阻',note:'尚缺原始数据'});await load('/plan?tab=执行',s);assert.match(await p.locator('.action-focus-paper').innerText(),/尚缺原始数据/);await shot('1440-执行队列');await p.locator('.action-queue-row h4 a').filter({hasText:s.tasks[0].title}).click();await p.getByRole('button',{name:'继续任务',exact:true}).click();await p.waitForURL(u=>u.pathname.startsWith('/work/'));assert.equal((await state()).tasks[0].id,s.tasks[0].id);await load('/plan?tab=执行&taskFilter=closed',s);assert.match(await p.locator('.action-focus-paper').innerText(),/从队列选择/);await load('/plan?tab=执行&task=missing',s);assert.match(await p.locator('.action-cycle').innerText(),/已不可访问/);assert.equal(await p.locator('.action-focus-controls').count(),0);});
await check('分步复盘恢复每任务草稿，校验必填，保存后不改变计划任务或预算',async()=>{const s=scenarioState('PT05'),id=s.tasks[0].id;s.tasks[0].note='已保存的本人行动记录（合成）';s.tasks.push({...makeTask(s,{title:'另一行动（合成）',hours:0,purpose:'另一个问题'}),id:'second'});await load('/plan?tab=复盘&task='+id,s);assert.equal(await p.getByLabel('活动类型',{exact:true}).inputValue(),'原创模拟实践');await p.locator('.review-source-record summary').click();await p.getByRole('button',{name:'引用到结果草稿',exact:true}).click();assert.equal(await p.getByLabel('实际结果与贡献',{exact:true}).inputValue(),s.tasks[0].note);await p.getByRole('button',{name:'保存复盘',exact:true}).click();assert.match(await p.getByRole('alert').innerText(),/请填写/);assert.equal(await p.getByLabel('原因分析',{exact:true}).isVisible(),true);await p.getByLabel('原因分析',{exact:true}).fill('输入字段缺少说明（合成）');await p.getByRole('button',{name:'下一步：填写改进措施',exact:false}).click();await p.getByLabel('改进措施',{exact:true}).fill('下次先列出字段与局限（合成）');await p.getByLabel('复盘任务',{exact:true}).selectOption('second');assert.equal(await p.getByLabel('实际结果与贡献',{exact:true}).inputValue(),'');await p.getByLabel('实际结果与贡献',{exact:true}).fill('独立的第二份草稿');await p.getByLabel('复盘任务',{exact:true}).selectOption(id);await p.reload();await p.locator('.action-review').waitFor();assert.equal(await p.getByLabel('实际结果与贡献',{exact:true}).inputValue(),s.tasks[0].note);await shot('1440-复盘记录');await p.getByRole('button',{name:'保存复盘',exact:true}).click();assert.equal(await p.locator('.review-saved-receipt').isVisible(),true);const next=await state();assert.equal(next.reviews.length,1);assert.equal(next.reviewDrafts[id],undefined);assert.equal(next.reviewDrafts.second.result,'独立的第二份草稿');for(const key of ['tasks','goal','budget','planVersion','claims'])assert.deepEqual(next[key],s[key]);await shot('1440-复盘回执');await p.locator('.review-history-entry>summary').click();assert.match(await p.locator('.review-history-entry').innerText(),/下次先列出字段/);await p.getByRole('button',{name:'修订复盘',exact:true}).click();assert.equal(await p.locator('dialog[open]').count(),1);});
await check('没有任务不展示无效表单；失效引用不显示其他行动草稿',async()=>{await load('/plan?tab=复盘','PT01');assert.equal(await p.locator('.review-journal form').count(),0);assert.equal(await p.getByRole('button',{name:'添加实践记录',exact:true}).isVisible(),true);await shot('1440-复盘起点');await load('/plan?tab=复盘&task=missing');assert.equal(await p.locator('.review-journal').count(),0);assert.match(await p.locator('.action-review').innerText(),/请重新选择/);});
await check('手机长行动与复盘上下文可往返并恢复键盘焦点',async()=>{const s=scenarioState('PT05');s.tasks[0].title='合成长行动标题用于检查折行'.repeat(8);s.tasks[0].note='已保存实际过程的合成测试内容。'.repeat(30);await load('/plan?tab=执行',s,390);await p.locator('.action-queue-row h4 a').first().click();await p.waitForFunction(()=>document.activeElement?.classList.contains('action-focus-paper'));await p.screenshot({path:dir+'/390-进入行动详情-视口.png'});await p.getByRole('button',{name:'返回行动队列 ↑',exact:true}).click();assert.equal(await p.locator('.action-queue-row [aria-current=true]').evaluate(e=>document.activeElement===e),true);await shot('390-执行长内容');await load('/plan?tab=复盘',s,390);await p.getByRole('button',{name:'查看任务记录 ↓',exact:true}).click();assert.equal(await p.locator('.review-action-context').evaluate(e=>document.activeElement===e),true);await p.screenshot({path:dir+'/390-回看行动记录-视口.png'});await p.getByRole('button',{name:'返回复盘记录 ↑',exact:true}).click();assert.equal(await p.locator('.review-journal').evaluate(e=>document.activeElement===e),true);await shot('390-复盘长内容');});
await check('桌面与手机空态、英文无溢出，主要按钮字号与触控尺寸正常',async()=>{for(const [name,route,s,lang]of [['390-执行起点','/plan?tab=执行','PT01','zh'],['390-复盘起点','/plan?tab=复盘','PT01','zh'],['390-执行英文','/plan?tab=执行','PT01','en'],['390-复盘英文','/plan?tab=复盘','PT01','en']]){await load(route,s,390,lang);assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.equal(await p.locator('.action-cycle').evaluate(e=>e.scrollWidth>e.clientWidth),false);if(lang==='en')assert.equal((await p.locator('.action-cycle').innerText()).match(/[\u4e00-\u9fff]+/g),null);const size=await p.locator('.action-cycle .primary').first().evaluate(e=>({font:parseFloat(getComputedStyle(e).fontSize),height:e.getBoundingClientRect().height}));assert.ok(size.font>=14&&size.height>=44,JSON.stringify(size));await shot(name);const last=p.locator('.action-cycle').locator('a,button').last();await last.scrollIntoViewIfNeeded();const a=await last.boundingBox(),flow=await p.locator('.flow-progress').boundingBox();assert.ok(a.y+a.height<flow.y+1);await p.screenshot({path:dir+'/'+name+'-底部.png'});}});
await check('原日程入口与活动记录不受列表重设计影响',async()=>{await load('/plan?tab=执行&view=calendar');assert.equal(await p.locator('.task-schedule').count(),1);assert.equal(await p.locator('.action-execution').count(),0);});
assert.deepEqual(errors,[]);results.push({name:'浏览器运行时错误',status:'pass',count:errors.length});
}finally{await fs.writeFile(dir+'/浏览器验收.json',JSON.stringify({results,errors},null,2));await browser.close();}
if(results.some(r=>r.status==='fail'))process.exitCode=1;
